<?php
namespace Tests\Feature;use App\Models\ActivityLog;use App\Models\Company;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class ReportsAndAuditTest extends TestCase{use RefreshDatabase;public function test_authenticated_mutation_is_audited():void{$user=User::factory()->create(['account_type'=>'company']);$this->actingAs($user,'sanctum')->getJson('/api/v1/company/profile');$this->actingAs($user,'sanctum')->putJson('/api/v1/company/profile',['name'=>'Empresa Auditada'])->assertOk();$this->assertDatabaseHas('activity_logs',['user_id'=>$user->id,'method'=>'PUT','response_status'=>200]);}public function test_admin_and_company_can_view_scoped_reports():void{$owner=User::factory()->create(['account_type'=>'company']);$company=Company::create(['name'=>'Acme','slug'=>'acme','status'=>'active']);$company->members()->attach($owner->id,['role'=>'owner','status'=>'active']);$this->actingAs($owner,'sanctum')->getJson('/api/v1/company/reports')->assertOk()->assertJsonPath('data.summary.jobs',0);$admin=User::factory()->create(['is_admin'=>true]);ActivityLog::create(['user_id'=>$owner->id,'company_id'=>$company->id,'action'=>'test','method'=>'POST','path'=>'/test','response_status'=>200]);$this->actingAs($admin,'sanctum')->getJson('/api/v1/admin/reports')->assertOk()->assertJsonPath('data.summary.companies',1)->assertJsonCount(1,'data.recent_activity');}public function test_candidate_cannot_view_company_reports():void{$this->actingAs(User::factory()->create(['account_type'=>'candidate']),'sanctum')->getJson('/api/v1/company/reports')->assertForbidden();}}
